INSERT IGNORE INTO ai_sql_cache (question, generated_sql, type, answer, is_valid) VALUES
('SmartRental là gì?', NULL, 'FAQ', 'SmartRental là nền tảng quản lý và tìm kiếm phòng trọ thông minh, giúp khách thuê tìm phòng dễ dàng và chủ trọ quản lý hiệu quả hơn với sự hỗ trợ của AI.', 1),
('Ứng dụng có miễn phí không?', NULL, 'FAQ', 'Dạ, SmartRental hoàn toàn miễn phí cho khách thuê. Bạn có thể tìm kiếm, đặt lịch và quản lý phòng mà không mất phí.', 1),
('AI chatbot có thể giúp gì?', NULL, 'FAQ', 'AI có thể giúp bạn tìm phòng theo tiêu chí, so sánh giá, xem hóa đơn, hợp đồng, phân tích ưu nhược điểm phòng và trả lời các thắc mắc về quy trình thuê.', 1),
('Làm sao để tìm phòng trọ?', NULL, 'FAQ', 'Bạn có thể dùng thanh tìm kiếm trên trang chủ, lọc theo quận, giá, diện tích. Hoặc hỏi AI như "Tìm phòng quận Gò Vấp dưới 3 triệu".', 1),
('Phòng trọ có những loại nào?', NULL, 'FAQ', 'Hệ thống có 6 loại: Studio, 1 Phòng ngủ, 2 Phòng ngủ, Phòng đơn, Phòng ở ghép và Phòng gác lửng.', 1),
('Giá phòng trọ trung bình bao nhiêu?', NULL, 'FAQ', 'Giá phụ thuộc khu vực và loại phòng. Bạn có thể hỏi AI "Tìm phòng tầm 3 triệu ở quận Bình Thạnh" để xem giá cụ thể.', 1),
('Phòng có nội thất không?', NULL, 'FAQ', 'Thông tin nội thất được ghi trong phần tiện nghi của mỗi phòng. Bạn xem chi tiết tại trang phòng trọ.', 1),
('Có thể xem phòng trực tuyến không?', NULL, 'FAQ', 'Dạ có, mỗi phòng đều có hình ảnh chi tiết. Bạn cũng có thể đặt lịch hẹn online để xem phòng trực tiếp.', 1),
('Làm sao đặt lịch xem phòng?', NULL, 'FAQ', 'Bạn vào trang chi tiết phòng, bấm nút Đặt lịch hẹn, chọn thời gian phù hợp. Chủ trọ sẽ xác nhận qua thông báo.', 1),
('Làm sao liên hệ chủ trọ?', NULL, 'FAQ', 'Sau khi đăng nhập, bạn có thể đặt lịch hẹn xem phòng qua app. Hệ thống sẽ tự động kết nối bạn với chủ trọ.', 1),
('Có cần đặt cọc không?', NULL, 'FAQ', 'Tiền cọc do chủ trọ quy định, thường bằng 1-2 tháng tiền thuê. Chi tiết sẽ được ghi rõ trong hợp đồng.', 1),
('Hợp đồng thuê kéo dài bao lâu?', NULL, 'FAQ', 'Thời hạn hợp đồng tùy thỏa thuận giữa bạn và chủ trọ, thường từ 6 tháng đến 1 năm.', 1),
('Thanh toán tiền phòng bằng cách nào?', NULL, 'FAQ', 'Hệ thống hỗ trợ thanh toán qua blockchain và chuyển khoản. Chi tiết sẽ được hướng dẫn sau khi ký hợp đồng.', 1),
('Làm sao đăng ký tài khoản?', NULL, 'FAQ', 'Bạn bấm Đăng ký trên app, điền thông tin cá nhân và xác minh email hoặc số điện thoại. Sau đó có thể đăng nhập ngay.', 1),
('Tôi cần đăng nhập để làm gì?', NULL, 'FAQ', 'Đăng nhập giúp bạn đặt lịch xem phòng, xem hợp đồng, theo dõi hóa đơn, nhận thông báo và sử dụng đầy đủ tính năng AI.', 1),
('Tôi quên mật khẩu thì làm sao?', NULL, 'FAQ', 'Bấm Quên mật khẩu ở trang đăng nhập, nhập email để nhận link đặt lại mật khẩu mới.', 1),
('SmartRental có an toàn không?', NULL, 'FAQ', 'Dạ, hệ thống sử dụng mã hóa dữ liệu, xác thực eKYC và blockchain để đảm bảo an toàn cho mọi giao dịch.', 1),
('Ekyc là gì?', NULL, 'FAQ', 'eKYC là xác minh danh tính điện tử bằng CCCD. Giúp đảm bảo an toàn cho giao dịch thuê phòng và bảo vệ quyền lợi các bên.', 1),
('Có thể đánh giá phòng không?', NULL, 'FAQ', 'Dạ có, sau khi thuê phòng bạn có thể đánh giá sao và viết nhận xét tại trang chi tiết phòng.', 1),
('Hỗ trợ kỹ thuật ở đâu?', NULL, 'FAQ', 'Bạn có thể liên hệ hỗ trợ qua AI chatbot hoặc gửi phản hồi trong mục Cài đặt của ứng dụng.', 1);
INSERT IGNORE INTO ai_sql_cache (question, generated_sql, type, answer, is_valid) VALUES
('Tiền điện nước tính như thế nào?', NULL, 'FAQ', 'Tiền điện nước được tính theo chỉ số đồng hồ hàng tháng nhân với đơn giá do chủ trọ quy định tại khu trọ.', 1),
('Làm sao thanh toán hóa đơn?', NULL, 'FAQ', 'Vào chi tiết hóa đơn, bấm Thanh toán. Hệ thống hỗ trợ thanh toán qua blockchain hoặc chuyển khoản.', 1),
('Hóa đơn bị tính sai thì làm sao?', NULL, 'FAQ', 'Bạn liên hệ chủ trọ qua hệ thống. Chủ trọ có quyền điều chỉnh chỉ số và tạo lại hóa đơn.', 1),
('Tiền phạt trễ hạn tính như nào?', NULL, 'FAQ', 'Phí phạt trễ hạn do chủ trọ quy định trong hợp đồng. Thông tin cụ thể nằm trong hóa đơn của bạn.', 1),
('Làm sao xin gia hạn hợp đồng?', NULL, 'FAQ', 'Bạn liên hệ chủ trọ qua hệ thống để thỏa thuận gia hạn. Hợp đồng mới sẽ được tạo khi hai bên đồng ý.', 1),
('Làm sao hủy hợp đồng sớm?', NULL, 'FAQ', 'Việc hủy sớm cần thông báo trước cho chủ trọ. Có thể phát sinh phí phạt theo điều khoản hợp đồng.', 1),
('Làm sao đổi phòng?', NULL, 'FAQ', 'Bạn cần thỏa thuận với chủ trọ về việc chấm dứt hợp đồng phòng cũ và ký hợp đồng phòng mới.', 1),
('Ekyc là gì tại sao cần xác minh?', NULL, 'FAQ', 'eKYC là xác minh danh tính bằng CCCD. Cần để đảm bảo an toàn cho giao dịch thuê phòng và bảo vệ quyền lợi.', 1),
('Reputation score là gì?', NULL, 'FAQ', 'Điểm uy tín phản ánh mức độ tin cậy, được tính từ lịch sử giao dịch, đánh giá và hành vi trên hệ thống.', 1),
('Phòng tôi có tiện nghi gì?', NULL, 'FAQ', 'Xem thông tin tiện nghi tại trang chi tiết phòng của bạn trong mục Phòng của tôi.', 1),
('Phòng bị hỏng báo ai?', NULL, 'FAQ', 'Bạn liên hệ chủ trọ qua hệ thống hoặc gửi yêu cầu bảo trì trong mục quản lý phòng.', 1),
('Tôi có thể thêm người ở cùng không?', NULL, 'FAQ', 'Việc thêm người ở cùng cần được chủ trọ đồng ý. Liên hệ chủ trọ qua hệ thống để thỏa thuận.', 1),
('Đánh giá phòng ở đâu?', NULL, 'FAQ', 'Bạn có thể đánh giá phòng tại trang chi tiết phòng sau khi có hợp đồng thuê.', 1),
('Làm sao xem thông báo?', NULL, 'FAQ', 'Bấm vào biểu tượng chuông ở góc trên bên phải màn hình để xem tất cả thông báo.', 1),
('Tôi muốn phản hồi dịch vụ', NULL, 'FAQ', 'Bạn có thể gửi phản hồi trong mục Cài đặt hoặc đánh giá trực tiếp tại trang phòng trọ.', 1);
INSERT IGNORE INTO ai_sql_cache (question, generated_sql, type, answer, is_valid) VALUES
('Làm sao đăng phòng cho thuê?', NULL, 'FAQ', 'Vào Quản lý phòng, bấm Thêm phòng. Điền thông tin, ảnh, giá thuê. AI sẽ tự động kiểm duyệt nội dung.', 1),
('Làm sao tạo khu trọ mới?', NULL, 'FAQ', 'Vào Quản lý khu trọ, bấm Thêm khu trọ. Điền địa chỉ, giá dịch vụ, ảnh. Admin sẽ duyệt trước khi hiển thị.', 1),
('Làm sao sửa thông tin phòng?', NULL, 'FAQ', 'Vào Quản lý phòng, chọn phòng cần sửa, bấm Chỉnh sửa. Cập nhật giá, mô tả, tiện nghi rồi lưu.', 1),
('AI kiểm duyệt nội dung như nào?', NULL, 'FAQ', 'AI Gemini kiểm tra văn bản và ảnh phòng, chấm điểm 0-100. Nội dung rác hoặc lừa đảo sẽ bị từ chối tự động.', 1),
('Làm sao tạo hóa đơn hàng tháng?', NULL, 'FAQ', 'Vào Quản lý hóa đơn, bấm Tạo hóa đơn. Nhập chỉ số điện nước mới, hệ thống tự tính tổng tiền.', 1),
('Doanh thu tính như thế nào?', NULL, 'FAQ', 'Doanh thu chỉ tính từ hóa đơn đã thanh toán (PAID). Hóa đơn chưa thu không được cộng vào tổng doanh thu.', 1),
('Làm sao nhắc khách đóng tiền?', NULL, 'FAQ', 'Vào Dashboard, bấm AI Nhắc nợ. AI sẽ soạn tin nhắn cá nhân hóa theo mức độ trễ hạn, bạn duyệt rồi gửi.', 1),
('Khách không ký hợp đồng thì sao?', NULL, 'FAQ', 'Hợp đồng cần cả hai bên ký. Bạn có thể gửi thông báo nhắc khách qua hệ thống hoặc hủy hợp đồng nháp.', 1),
('AI tư vấn pháp lý hợp đồng?', NULL, 'FAQ', 'Dạ có, khi xem hợp đồng bấm AI Tư vấn để AI phân tích rủi ro pháp lý và đề xuất chỉnh sửa điều khoản.', 1),
('Phân tích bất thường điện nước ở đâu?', NULL, 'FAQ', 'Vào Dashboard, bấm AI Phân tích bất thường. AI so sánh mức tiêu thụ từng phòng với tháng trước và mặt bằng chung.', 1),
('Điểm uy tín chủ trọ là gì?', NULL, 'FAQ', 'Điểm uy tín phản ánh mức độ tin cậy dựa trên đánh giá từ khách thuê, lịch sử giao dịch và hành vi trên hệ thống.', 1),
('Làm sao xóa phòng?', NULL, 'FAQ', 'Vào Quản lý phòng, chọn phòng, bấm Ẩn hoặc Xóa. Lưu ý phòng đang có hợp đồng không thể xóa.', 1),
('Có thể xem đánh giá từ khách không?', NULL, 'FAQ', 'Dạ có, vào trang chi tiết phòng hoặc khu trọ để xem tất cả đánh giá và số sao từ khách thuê.', 1),
('Làm sao thêm tiện ích cho phòng?', NULL, 'FAQ', 'Vào Quản lý phòng, chọn phòng, bấm Chỉnh sửa và cập nhật danh sách tiện nghi.', 1),
('Có báo cáo xuất file không?', NULL, 'FAQ', 'Hiện tại bạn có thể xem báo cáo doanh thu, tỷ lệ lấp đầy trực tiếp trên Dashboard.', 1);
